public function findCheaperThan(float $maxPrice): QueryResultInterface
{
    $query = $this->createQuery();
    $query->matching($query->lessThan('price', $maxPrice));
    $query->setOrderings(['price' => QueryInterface::ORDER_ASCENDING]);
    return $query->execute();
}

